import {
  FAMILY_NAMES,
  candidateFromGraph,
  createGraph,
  randomSeed,
} from "./generator.js";
import { descriptorDistance } from "./perception.js";

const clamp01 = (value) => Math.max(0, Math.min(1, value));

function mix(a, b, amount) {
  return a + (b - a) * amount;
}

/**
 * Bias the authored grammar towards visually articulated, layered outputs.
 * The transformation is deterministic for a given seed because it only uses
 * values already generated by createGraph(). It does not optimise against a
 * visitor model and does not infer preference.
 */
export function enrichGraph(graph) {
  const next = structuredClone(graph);
  const t = next.traits;

  t.complexity = mix(0.68, 1, t.complexity);
  t.density = mix(0.28, 1, t.density);
  t.turbulence = mix(0.18, 1, t.turbulence);
  t.depth = mix(0.24, 1, t.depth);
  t.contrast = mix(0.18, 0.94, t.contrast);

  // Preserve quiet and sparse regions within complex programs. Complexity is
  // not treated as uniform maximal density.
  if (t.softness > 0.72) t.density *= 0.72;
  if (t.symmetry > 0.82) t.rotation = 1 - t.rotation;
  if (t.tempo > 0.86) t.tempo = 0.55 + (t.tempo - 0.86) * 0.45;

  next.generator = "tsdne-procedural-v1";
  return next;
}

export function generateComplexCandidate(seed = randomSeed(), family = null) {
  const graph = enrichGraph(createGraph(seed, family));
  return candidateFromGraph(graph, {
    seed,
    origin: "authored-procedural",
  });
}

export function visualComplexityScore(candidate) {
  const p = candidate.perception;
  if (!p) return 0;

  const variance = clamp01(Math.sqrt(Math.max(0, p.variance)) / 112);
  const edge = clamp01(p.edge / 58);
  const motion = clamp01(p.temporal / 36);
  const dynamicRange = clamp01(1 - Math.abs(p.mean - 126) / 126);
  const saturationBalance = clamp01(1 - Math.abs(p.saturation - 0.28) / 0.72);
  const programDepth = clamp01((candidate.estimatedCost - 5) / 12);

  return (
    variance * 0.24 +
    edge * 0.24 +
    motion * 0.14 +
    dynamicRange * 0.14 +
    saturationBalance * 0.1 +
    programDepth * 0.14
  );
}

export function nearestPerceptualDistance(candidate, traces) {
  if (!traces.length) return 1;
  let nearest = 1;
  for (const trace of traces) {
    nearest = Math.min(nearest, descriptorDistance(candidate.perception, trace.perception));
  }
  return nearest;
}

export function familyDistance(candidate, recentFamilies) {
  if (!recentFamilies.length) return 1;
  const latest = recentFamilies.at(-1);
  if (candidate.family === latest) return 0;
  const occurrences = recentFamilies.filter((family) => family === candidate.family).length;
  return clamp01(1 - occurrences / Math.max(2, recentFamilies.length));
}

/**
 * Selects a candidate by maximin perceptual distance, quality and temporary
 * family separation. This is sequence-level quality control, not a model of
 * the visitor. All traces are local, bounded and non-reconstructive.
 */
export function scoreCandidate(
  candidate,
  traces,
  recentFamilies,
  { earlyEncounter = false } = {},
) {
  const novelty = nearestPerceptualDistance(candidate, traces);
  const complexity = visualComplexityScore(candidate);
  const family = familyDistance(candidate, recentFamilies);

  const weights = earlyEncounter
    ? { novelty: 0.67, complexity: 0.2, family: 0.13 }
    : { novelty: 0.56, complexity: 0.31, family: 0.13 };

  return {
    score:
      novelty * weights.novelty +
      complexity * weights.complexity +
      family * weights.family,
    novelty,
    complexity,
    family,
  };
}

export function selectCandidate(
  candidates,
  traces,
  recentFamilies,
  { earlyEncounter = false } = {},
) {
  if (!candidates.length) throw new Error("No valid candidates were available.");

  const ranked = candidates
    .map((candidate) => ({
      candidate,
      ...scoreCandidate(candidate, traces, recentFamilies, { earlyEncounter }),
    }))
    .sort((a, b) => b.score - a.score);

  return ranked[0];
}

export function familySchedule(recentFamilies, count = FAMILY_NAMES.length) {
  const latest = recentFamilies.at(-1);
  const penultimate = recentFamilies.at(-2);
  const available = FAMILY_NAMES.filter(
    (family) => family !== latest && family !== penultimate,
  );
  const source = available.length >= 4 ? available : FAMILY_NAMES;
  const offset = recentFamilies.length % source.length;
  return Array.from({ length: count }, (_, index) => source[(offset + index) % source.length]);
}
